package com.wildforge.worldgen;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/** Loads the biome profiles generated by ContentDataGenerator from a JAR-safe index. */
public final class BiomeCatalog {
    private static final String INDEX = "data/wildforge/worldgen/biomes/index.json";
    private final Map<Biome, BiomeProfile> profiles;

    public BiomeCatalog(Map<Biome, BiomeProfile> profiles) {
        EnumMap<Biome, BiomeProfile> copy = new EnumMap<>(Biome.class);
        copy.putAll(profiles);
        for (Biome biome : Biome.values()) {
            if (!copy.containsKey(biome)) {
                throw new IllegalArgumentException("Missing biome profile " + biome);
            }
        }
        this.profiles = Map.copyOf(copy);
    }

    public BiomeProfile get(Biome biome) { return profiles.get(biome); }
    public Map<Biome, BiomeProfile> all() { return profiles; }

    public Biome select(double temperature, double rainfall, int heightAboveSea,
                        Geology geology, boolean coastal, boolean floodplain) {
        Biome winner = Biome.SUNMEADOW_PLAINS;
        double best = Double.NEGATIVE_INFINITY;
        for (Biome biome : Biome.values()) {
            BiomeProfile profile = profiles.get(biome);
            if (!profile.matches(temperature, rainfall, heightAboveSea,
                    geology, coastal, floodplain)) continue;
            // Priority handles rare terrain-specific biomes. Climate-center closeness
            // breaks ties without letting an unrelated region win the biome lottery.
            double tempMid = (profile.temperature().min() + profile.temperature().max()) * 0.5;
            double rainMid = (profile.rainfall().min() + profile.rainfall().max()) * 0.5;
            double score = profile.priority() * 10.0
                    - Math.abs(temperature - tempMid) * 1.2
                    - Math.abs(rainfall - rainMid) * 1.2;
            if (score > best) {
                best = score;
                winner = profile.biome();
            }
        }
        return winner;
    }

    public static BiomeCatalog loadBuiltIn() throws IOException {
        ClassLoader loader = BiomeCatalog.class.getClassLoader();
        JsonObject index = readObject(loader, INDEX);
        JsonArray array = index.getAsJsonArray("biomes");
        if (array == null) throw new IOException("Missing biome index array");
        Map<Biome, BiomeProfile> profiles = new EnumMap<>(Biome.class);
        for (JsonElement entry : array) {
            String path = entry.getAsString();
            if (!path.startsWith("data/wildforge/worldgen/biomes/")
                    || !path.endsWith(".json") || path.contains("..")) {
                throw new IOException("Invalid biome path " + path);
            }
            BiomeProfile profile = parse(readObject(loader, path));
            if (profiles.putIfAbsent(profile.biome(), profile) != null) {
                throw new IOException("Duplicate biome profile " + profile.biome());
            }
        }
        if (profiles.size() != Biome.values().length) {
            throw new IOException("Expected " + Biome.values().length
                    + " surface biomes, got " + profiles.size());
        }
        return new BiomeCatalog(profiles);
    }

    public static BiomeCatalog loadBuiltInUnchecked() {
        try {
            return loadBuiltIn();
        } catch (IOException failure) {
            throw new IllegalStateException("Could not load generated surface biome profiles", failure);
        }
    }

    private static JsonObject readObject(ClassLoader loader, String path) throws IOException {
        try (InputStream stream = loader.getResourceAsStream(path)) {
            if (stream == null) throw new IOException("Missing generated biome resource " + path);
            try (InputStreamReader reader = new InputStreamReader(stream, StandardCharsets.UTF_8)) {
                return JsonParser.parseReader(reader).getAsJsonObject();
            }
        } catch (RuntimeException e) {
            throw new IOException("Invalid generated biome JSON at " + path, e);
        }
    }

    private static BiomeProfile parse(JsonObject json) throws IOException {
        try {
            Biome biome = Biome.valueOf(json.get("id").getAsString()
                    .replace("wildforge:", "").toUpperCase(java.util.Locale.ROOT));
            JsonObject criteria = json.getAsJsonObject("criteria");
            JsonObject surface = json.getAsJsonObject("surface");
            JsonObject decor = json.getAsJsonObject("decorations");
            List<Geology> geology = new ArrayList<>();
            for (JsonElement entry : criteria.getAsJsonArray("geology")) {
                geology.add(Geology.valueOf(entry.getAsString()));
            }
            return new BiomeProfile(biome, json.get("name").getAsString(),
                    Integer.parseInt(json.get("map_color").getAsString(), 16),
                    range(criteria.getAsJsonArray("temperature")),
                    range(criteria.getAsJsonArray("rainfall")),
                    range(criteria.getAsJsonArray("height_above_sea")),
                    geology, criteria.get("coastal").getAsBoolean(),
                    criteria.get("floodplain").getAsBoolean(),
                    criteria.get("priority").getAsInt(),
                    surface.get("top").getAsString(),
                    surface.get("filler").getAsString(),
                    decor.get("tree_density").getAsDouble(),
                    decor.get("plant_density").getAsDouble(),
                    decor.get("max_tree_slope").getAsInt(),
                    decor.get("max_plant_slope").getAsInt(),
                    features(decor.getAsJsonArray("trees")),
                    features(decor.getAsJsonArray("plants")));
        } catch (RuntimeException e) {
            throw new IOException("Invalid surface biome profile " + json, e);
        }
    }

    private static BiomeProfile.Range range(JsonArray values) {
        if (values.size() != 2) throw new IllegalArgumentException("Expected two range bounds");
        return new BiomeProfile.Range(values.get(0).getAsDouble(), values.get(1).getAsDouble());
    }

    private static List<BiomeProfile.WeightedFeature> features(JsonArray entries) {
        List<BiomeProfile.WeightedFeature> result = new ArrayList<>();
        for (JsonElement entry : entries) {
            JsonObject value = entry.getAsJsonObject();
            result.add(new BiomeProfile.WeightedFeature(
                    value.get("id").getAsString(), value.get("weight").getAsInt()));
        }
        return result;
    }
}
